export async function listTools() {
  return [{
    name: 'format_value',
    description: 'Format a value as text (uppercased) or integer (numeric text).',
    inputSchema: {
      type: 'object',
      properties: {
        value: { type: 'string' },
        kind: { type: 'string', enum: ['text', 'integer'] }
      },
      required: ['value', 'kind'],
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args) {
  if (name !== 'format_value') {
    const err = new Error('Unknown tool: ' + name);
    err.code = -32602;
    throw err;
  }
  // validate
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    const err = new Error('Invalid arguments');
    err.code = -32602;
    throw err;
  }
  // check for extra fields
  const allowed = new Set(['value', 'kind']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      const err = new Error('Unknown field: ' + key);
      err.code = -32602;
      throw err;
    }
  }
  const { value, kind } = args;
  if (typeof value !== 'string') {
    const err = new Error('value must be a string');
    err.code = -32602;
    throw err;
  }
  if (kind !== 'text' && kind !== 'integer') {
    const err = new Error('kind must be text or integer');
    err.code = -32602;
    throw err;
  }
  if (kind === 'text') {
    return { content: [{ type: 'text', text: value.toUpperCase() }] };
  } else {
    // integer: parse base-10 integer
    const trimmed = value.trim();
    if (!/^[+-]?\d+$/.test(trimmed)) {
      const err = new Error('Malformed integer: ' + value);
      err.code = -32602;
      throw err;
    }
    const num = parseInt(trimmed, 10);
    return { content: [{ type: 'text', text: String(num) }] };
  }
}
